window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3da9c0988f074adc"]={"versions": [{"id": "FIG-3da9c0988f074adc", "releases": ["R17-03_R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der AUTOSAR Adaptive Platform (Manifest-Spezifikation). Das Diagramm spezifiziert die strukturelle Verankerung des internen Verhaltens (<code>AdaptiveSwcInternalBehavior</code>) und dessen Dienstabhängigkeiten (<code>SwcServiceDependency</code>) im Kontext von Software-Komponententypen der Adaptive Platform zur Modellierung von <code>DiagnosticServiceSwMapping</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Metaklassen und deren hierarchische Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>AdaptiveApplicationSwComponentType</code> (Spezialisierung von <code>SwComponentType</code>): Repräsentiert den komponentenbezogenen Applikationstyp der Adaptive Platform. Enthält über die Kompositionsrolle <code>+internalBehavior</code> mit der Multiplizität 0..1 eine Instanz von <code>AdaptiveSwcInternalBehavior</code>.\n</li><li><code>AdaptiveSwcInternalBehavior</code>: Modelliert das interne Verhalten einer adaptiven Anwendungskomponente. Aggregiert über die Kompositionsrolle <code>+serviceDependency</code> mit der Multiplizität 0..* Instanzen von <code>SwcServiceDependency</code>.\n</li><li><code>SwcServiceDependency</code> (Spezialisierung/Realisierung von <code>AtpStructureElement</code>, <code>Identifiable</code> und <code>ServiceDependency</code>): Definiert die konkrete Dienstabhängigkeit einer Softwarekomponente, welche für das Mapping diagnostischer Dienste herangezogen wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es stellt keine dynamischen Laufzeit- oder Sequenzabläufe dar. Es definiert die statische Deklarationshierarchie vom Komponententyp über das interne Verhalten bis zu den Dienstabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich für die Konfiguration des internen Komponentenverhaltens zur Realisierung von <code>DiagnosticServiceSwMapping</code>. Entwickler und Modellierungswerkzeuge müssen sicherstellen, dass einer <code>AdaptiveApplicationSwComponentType</code> maximal ein <code>AdaptiveSwcInternalBehavior</code> zugeordnet ist. Das Mapping von Diagnosediensten setzt zwingend voraus, dass innerhalb dieses <code>AdaptiveSwcInternalBehavior</code> entsprechende <code>SwcServiceDependency</code>-Elemente definiert sind.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-735799d9663dbbb2", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der AUTOSAR Adaptive Platform (Manifest-Spezifikation). Das Diagramm spezifiziert die strukturelle Verankerung des internen Verhaltens (<code>AdaptiveSwcInternalBehavior</code>) und dessen Dienstabhängigkeiten (<code>SwcServiceDependency</code>) im Kontext von Software-Komponententypen der Adaptive Platform zur Modellierung von <code>DiagnosticServiceSwMapping</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Metaklassen und deren hierarchische Kompositionsbeziehungen unter Berücksichtigung von Variabilität und Splittbarkeit:</p>\n<ul class=\"fig-list\"><li><code>AdaptiveApplicationSwComponentType</code> (Spezialisierung von <code>SwComponentType</code>): Repräsentiert den komponentenbezogenen Applikationstyp der Adaptive Platform. Enthält über die Kompositionsrolle <code>+internalBehavior</code> mit der Multiplizität 0..1 und den Stereotypen <code>«atpVariation,atpSplitable»</code> eine Instanz von <code>AdaptiveSwcInternalBehavior</code>.\n</li><li><code>AdaptiveSwcInternalBehavior</code> (Spezialisierung von <code>Identifiable</code>): Modelliert das identifizierbare interne Verhalten einer adaptiven Anwendungskomponente. Aggregiert über die Kompositionsrolle <code>+serviceDependency</code> mit der Multiplizität 0..* Instanzen von <code>SwcServiceDependency</code>.\n</li><li><code>SwcServiceDependency</code> (Spezialisierung/Realisierung von <code>AtpStructureElement</code>, <code>Identifiable</code> und <code>ServiceDependency</code>): Definiert die konkrete Dienstabhängigkeit einer Softwarekomponente für das Mapping diagnostischer Dienste.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es stellt keine dynamischen Laufzeit- oder Sequenzabläufe dar. Es definiert die statische Deklarationshierarchie vom Komponententyp über das interne Verhalten bis zu den Dienstabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich für die Konfiguration und Manifest-Modellierung. Durch die Kennzeichnung der Relation <code>+internalBehavior</code> als <code>«atpVariation,atpSplitable»</code> kann die Zuordnung des internen Verhaltens variabilitätsabhängig gebunden sowie auf mehrere Manifest-Dateien aufgeteilt (gesplittet) werden. Da <code>AdaptiveSwcInternalBehavior</code> als <code>Identifiable</code> ausgewiesen ist, besitzt es einen eigenen eindeutigen Kurznamen (<code>shortName</code>) im Namensraum.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5f24d519a044c47c", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der AUTOSAR Adaptive Platform (Manifest-Spezifikation). Das Diagramm spezifiziert die strukturelle Verankerung des internen Verhaltens (<code>AdaptiveSwcInternalBehavior</code>) und dessen Dienstabhängigkeiten (<code>SwcServiceDependency</code>) im Kontext von Software-Komponententypen der Adaptive Platform zur Modellierung von <code>DiagnosticServiceSwMapping</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Metaklassen und deren hierarchische Kompositionsbeziehungen unter Berücksichtigung von Variabilität und Splittbarkeit:</p>\n<ul class=\"fig-list\"><li><code>AdaptiveApplicationSwComponentType</code> (Spezialisierung von <code>SwComponentType</code>): Repräsentiert den komponentenbezogenen Applikationstyp der Adaptive Platform. Enthält über die Kompositionsrolle <code>+internalBehavior</code> mit der Multiplizität 0..1 und den Stereotypen <code>«atpVariation,atpSplitable»</code> eine Instanz von <code>AdaptiveSwcInternalBehavior</code>.\n</li><li><code>AdaptiveSwcInternalBehavior</code> (Spezialisierung von <code>Identifiable</code>): Modelliert das identifizierbare interne Verhalten einer adaptiven Anwendungskomponente. Aggregiert über die Kompositionsrolle <code>+serviceDependency</code> mit der Multiplizität 0..* Instanzen von <code>SwcServiceDependency</code>.\n</li><li><code>SwcServiceDependency</code> (Spezialisierung/Realisierung von <code>AtpStructureElement</code>, <code>Identifiable</code> und <code>ServiceDependency</code>): Definiert die konkrete Dienstabhängigkeit einer Softwarekomponente für das Mapping diagnostischer Dienste.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es stellt keine dynamischen Laufzeit- oder Sequenzabläufe dar. Es definiert die statische Deklarationshierarchie vom Komponententyp über das interne Verhalten bis zu den Dienstabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich für die Konfiguration und Manifest-Modellierung. Durch die Kennzeichnung der Relation <code>+internalBehavior</code> als <code>«atpVariation,atpSplitable»</code> kann die Zuordnung des internen Verhaltens variabilitätsabhängig gebunden sowie auf mehrere Manifest-Dateien aufgeteilt (gesplittet) werden. Da <code>AdaptiveSwcInternalBehavior</code> als <code>Identifiable</code> ausgewiesen ist, besitzt es einen eigenen eindeutigen Kurznamen (<code>shortName</code>) im Namensraum.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-689b397360f83ff9", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der AUTOSAR Adaptive Platform (Manifest-Spezifikation). Das Diagramm spezifiziert die strukturelle Verankerung des internen Verhaltens (<code>AdaptiveSwcInternalBehavior</code>) und dessen Dienstabhängigkeiten (<code>SwcServiceDependency</code>) im Kontext von Software-Komponententypen der Adaptive Platform zur Modellierung von <code>DiagnosticServiceSwMapping</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Metaklassen und deren hierarchische Kompositionsbeziehungen unter Berücksichtigung von Variabilität und Splittbarkeit:</p>\n<ul class=\"fig-list\"><li><code>AdaptiveApplicationSwComponentType</code> (Spezialisierung von <code>SwComponentType</code>): Repräsentiert den komponentenbezogenen Applikationstyp der Adaptive Platform. Enthält über die Kompositionsrolle <code>+internalBehavior</code> mit der Multiplizität 0..1 und den Stereotypen <code>«atpVariation,atpSplitable»</code> eine Instanz von <code>AdaptiveSwcInternalBehavior</code>.\n</li><li><code>AdaptiveSwcInternalBehavior</code> (Spezialisierung von <code>Identifiable</code>): Modelliert das identifizierbare interne Verhalten einer adaptiven Anwendungskomponente. Aggregiert über die Kompositionsrolle <code>+serviceDependency</code> mit der Multiplizität 0..* Instanzen von <code>SwcServiceDependency</code>.\n</li><li><code>SwcServiceDependency</code> (Spezialisierung/Realisierung von <code>AtpStructureElement</code>, <code>Identifiable</code> und <code>ServiceDependency</code>): Definiert die konkrete Dienstabhängigkeit einer Softwarekomponente für das Mapping diagnostischer Dienste.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es stellt keine dynamischen Laufzeit- oder Sequenzabläufe dar. Es definiert die statische Deklarationshierarchie vom Komponententyp über das interne Verhalten bis zu den Dienstabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich für die Konfiguration und Manifest-Modellierung. Durch die Kennzeichnung der Relation <code>+internalBehavior</code> als <code>«atpVariation,atpSplitable»</code> kann die Zuordnung des internen Verhaltens variabilitätsabhängig gebunden sowie auf mehrere Manifest-Dateien aufgeteilt (gesplittet) werden. Da <code>AdaptiveSwcInternalBehavior</code> als <code>Identifiable</code> ausgewiesen ist, besitzt es einen eigenen eindeutigen Kurznamen (<code>shortName</code>) im Namensraum.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-3da9c0988f074adc", "to": "FIG-735799d9663dbbb2", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Die Metaklasse <code>AdaptiveSwcInternalBehavior</code> erbt nun von der Basismetavorschrift <code>Identifiable</code> (oben rechts im Klassenkopf annotiert).\n</li><li>Die Kompositionsbeziehung <code>AdaptiveApplicationSwComponentType</code> zu <code>AdaptiveSwcInternalBehavior</code> (<code>+internalBehavior</code>) wurde mit den Stereotypen <code>«atpVariation,atpSplitable»</code> versehen.\n</li></ul>"}, {"from": "FIG-735799d9663dbbb2", "to": "FIG-5f24d519a044c47c", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5f24d519a044c47c", "to": "FIG-689b397360f83ff9", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
